package com.securebiz.shared.security;
import com.fasterxml.jackson.databind.ObjectMapper;import com.securebiz.identity.security.SecurityPrincipal;import com.securebiz.securitydata.service.DeniedAccessRecorder;import com.securebiz.shared.api.ApiError;import com.securebiz.shared.config.CorrelationIdFilter;import jakarta.servlet.http.*;import org.springframework.http.MediaType;import org.springframework.security.access.AccessDeniedException;import org.springframework.security.core.Authentication;import org.springframework.security.web.access.AccessDeniedHandler;import org.springframework.stereotype.Component;import java.io.IOException;import java.time.Instant;import java.util.List;
@Component public class ApiAccessDeniedHandler implements AccessDeniedHandler{private final DeniedAccessRecorder recorder;private final ObjectMapper json;public ApiAccessDeniedHandler(DeniedAccessRecorder recorder,ObjectMapper json){this.recorder=recorder;this.json=json;}@Override public void handle(HttpServletRequest request,HttpServletResponse response,AccessDeniedException ex)throws IOException{Authentication auth=org.springframework.security.core.context.SecurityContextHolder.getContext().getAuthentication();if(auth!=null&&auth.getPrincipal()instanceof SecurityPrincipal p)recorder.record(p.userId(),p.sessionId(),request.getRequestURI(),request.getMethod(),request.getRemoteAddr(),request.getHeader("User-Agent"));response.setStatus(403);response.setContentType(MediaType.APPLICATION_JSON_VALUE);Object correlation=request.getAttribute(CorrelationIdFilter.ATTRIBUTE);json.writeValue(response.getOutputStream(),new ApiError(Instant.now(),403,"ACCESS_DENIED","You do not have permission to perform this action",correlation==null?null:correlation.toString(),List.of()));}}
